"""Independent Python transcription of ets.rs; no Rust/native build or DLL calls.
RN53(RN64()) is implemented by exact rational arithmetic, ties to even.
"""
import math
import struct
from fractions import Fraction as Q

PARAMETERS = [(0.9,.001),(.9,.899),(.833333,.75),(.75,.001),(.75,.749),
 (.666667,.166667),(.666667,.5),(.5,.001),(.5,.25),(.5,.499),
 (.333333,.166667),(.25,.001),(.25,.249),(.166667,.0833333),
 (.126,.001),(.126,.125),(.1,.001),(.1,.099),(.002,.001),
 (.998,.099),(.998,.499),(.998,.749),(.998,.899)]
EPS = 2.**-52

def bits(x):
    return struct.pack('>d', float(x)).hex()

def val(x):
    return {'value': x, 'bits': bits(x)}

def rnq(x, precision=64):
    if not x:
        return Q(0)
    sign = -1 if x < 0 else 1
    x = abs(x)
    e = x.numerator.bit_length() - x.denominator.bit_length()
    unit = Q(2)**e
    if x < unit:
        e -= 1
    unit = Q(2)**(e-precision+1)
    y = x/unit
    k, rem = divmod(y.numerator,y.denominator)
    if rem*2 > y.denominator or (rem*2 == y.denominator and k%2):
        k += 1
    return sign*k*unit

def xop(a,b,op):
    a,b=Q(a),Q(b)
    return float(rnq({'add':lambda:a+b,'sub':lambda:a-b,
                     'mul':lambda:a*b,'div':lambda:a/b}[op]()))

def slope(y):
    sx=sy=sxx=sxy=0.
    for i,v in enumerate(y):
        x=float(i+1)
        sx+=x; sy+=v; sxx+=x*x; sxy+=x*v
    n=float(len(y))
    return (n*sxy-sx*sy)/(n*sxx-sx*sx)

def extend(y):
    out=list(y)
    r=slope(y)
    for j in range(len(y),7):
        out.append(y[j%2]+float(j-j%2)*r)
    return out

def initial_slope(y):
    return slope(extend(y)) if len(y)<7 else slope(y)

def window(n):
    return n if n<=10 else min(10,int(float(n)*.4))

def run(y,a,b,g=EPS,initial=None,validation=None):
    if initial is None:
        l,t,s=y[0],initial_slope(y),[0.,0.]
    else:
        l,t,s=initial[0],initial[1],list(initial[2])
    p=len(s)
    errors=[0.]; preds=[y[0]]; trends=[]
    for j,v in enumerate(y[1:],1):
        q=j%p
        pred=(l+t)+s[q]
        e=v-pred
        errors.append(e); preds.append(pred)
        if validation is not None and j>=validation:
            l+=t
        else:
            l+=t+a*e
            t+=b*e
            s[q]+=g*e
        trends.append(t)
    return dict(level=l,trend=t,seasons=s,errors=errors,preds=preds,trends=trends)

def sse(m):
    total=0.
    for e in m['errors']:
        total+=e*e
    return total

def stats(y,m,lag=1):
    n=len(y); w=window(n); start=n-w
    ae=ss=sm=0.
    for j in range(start,n):
        e=m['errors'][j]; f=m['preds'][j]
        ae+=abs(e); ss+=e*e
        denom=(abs(y[j])+abs(f))/2.
        sm+=abs(e)/denom if denom else 0.
    mae=ae/float(w)
    prefix=start if start else n
    scale=sum(abs(y[j]-y[j-lag]) for j in range(lag,prefix))/float(prefix-lag)
    return [mae/scale if scale else 0.,sm/float(w),mae,math.sqrt(ss/float(w))]

def finish(y,m,b):
    n=len(y); count=(n if n<=10 else (n+1)//2)-1
    d=float((n if n<=10 else n//2)-1)
    total=squares=0.
    for t in m['trends'][-count:]:
        total=xop(total,t,'add'); squares=xop(squares,xop(t,t,'mul'),'add')
    mean=xop(total,d,'div')
    var=xop(xop(squares,d,'div'),xop(mean,mean,'mul'),'sub')
    root=math.sqrt(var) if var>=0 else math.nan
    threshold=xop(xop(root,float(d+1),'mul'),d,'div') if math.isfinite(root) else math.nan
    reset=abs(mean)<threshold
    if reset:
        m['level']=y[-1]-m['seasons'][(n-1)%2]
        m['trend']=initial_slope(y)
        b=.001
    center=(m['seasons'][0]+m['seasons'][1])/2.
    m['level']+=center
    m['seasons']=[s-center for s in m['seasons']]
    return b,reset

def fit(y,pool=PARAMETERS,score_kind='double',last=False):
    ey=extend(y) if len(y)<7 else y
    start=len(ey)-window(len(ey))
    best=math.inf; chosen=None; scores=[]
    for a,b in pool:
        m=run(ey,a,b,validation=start or None)
        if score_kind=='double':
            score=sse(m)
        elif score_kind=='pc64':
            total=Q(0)
            for e in m['errors']:
                total=rnq(total+rnq(Q(e)*Q(e)))
            score=float(total)
        elif score_kind=='wide_sum':
            score=float(sum((Q(e*e) for e in m['errors']),Q(0)))
        else:
            raise ValueError(score_kind)
        scores.append((a,b,score))
        if score<best or (last and score==best):
            best=score; chosen=(a,b)
    a,b=chosen
    m=run(y,a,b)
    st=stats(y,m); ss=sse(m)
    corrected,reset=finish(y,m,b)
    return dict(a=a,b=corrected,raw_b=b,g=EPS,model=m,stats=st,sse=ss,
                reset=reset,scores=scores,initial_slope=initial_slope(y))

def forecast(y,fit,h):
    m=fit['model']; p=len(m['seasons'])
    return xop(m['level']+float(h)*m['trend'],m['seasons'][(len(y)-1+h)%p],'add')

def variance(a,b,g,p,h):
    h=float(h); k=math.floor((h-1.)/float(p))
    v=1.+(h-1.)*((h*a*b+h*(2.*h-1.)*b*b/6.)+a*a)
    return v+g*k*((2.*a+g)+float(p)*b*(k+1.))

def ci(y,f,h,z=1.):
    v=variance(f['a'],f['b'],f['g'],len(f['model']['seasons']),h)
    return xop(z,math.sqrt((f['sse']/float(len(y)))*v),'mul')

def seasonal_initial(y,p,kind):
    b=sum(y[j+p]-y[j] for j in range(p))/float(p*p)
    if kind=='prefix':
        adjusted=[y[j]-float(j)*b for j in range(p)]
    elif kind=='phase_mean':
        adjusted=[sum(y[j]-float(j)*b for j in range(q,len(y),p))/len(range(q,len(y),p)) for q in range(p)]
    elif kind=='phase_regression':
        num=den=0.
        for q in range(p):
            indices=list(range(q,len(y),p))
            xm=sum(indices)/len(indices); ym=sum(y[j] for j in indices)/len(indices)
            for j in indices:
                num+=(j-xm)*(y[j]-ym); den+=(j-xm)**2
        b=num/den
        adjusted=[sum(y[j]-float(j)*b for j in range(q,len(y),p))/len(range(q,len(y),p)) for q in range(p)]
    else:
        raise ValueError(kind)
    l=sum(adjusted)/float(p)
    return l,b,[v-l for v in adjusted]

def seasonal_fit(y,p,a,b,g,kind):
    initial=seasonal_initial(y,p,kind)
    m=run(y,a,b,g,initial)
    return dict(a=a,b=b,g=g,model=m,stats=stats(y,m),sse=sse(m),initial=initial)
